define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_10.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e86339","topics":[]},{"title":"<span class=\"ph\">Shutting down<span class=\"ph\">\/powering off<\/span> the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_Parent_18.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e86441","topics":[]},{"title":"Applying LOTO - Integrated System Cabinet (ISC)","shortdesc":"<p class=\"shortdesc\">Apply LOTO to the Power Distribution Unit (PDU) when servicing this item in the Integrated System Cabinet (ISC). Applying LOTO ensures a safe environment when working on this part.<\/p>","href":"t_LOTO-for-ISC-Integrated-System-Cabinet_14845718_17.html","attributes":{"data-id":"id_13106290"},"menu":{"hasChildren":false},"tocID":"id_13106290-d46e86547","topics":[]},{"title":"Removing the Integrated System Cabinet (ISC) Ethernet Switch","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_RemovingTheISCEthernetSwitch.html","attributes":{"data-id":"id_2014301"},"menu":{"hasChildren":false},"tocID":"id_2014301-d46e86649","topics":[]},{"title":"Installing the Integrated System Cabinet (ISC) Ethernet Switch","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_InstallingTheISCEthernetSwitch.html","attributes":{"data-id":"id_2014302"},"menu":{"hasChildren":false},"tocID":"id_2014302-d46e86750","topics":[]},{"title":"Removing LOTO - Integrated System Cabinet (ISC)","shortdesc":"<p class=\"shortdesc\">Removing locks and tags, and restoring power to the ISC (Integrated System Cabinet) Power Distribution Unit (PDU).<\/p>","href":"t_Removing-LOTO-ISC-Pioneer_17.html","attributes":{"data-id":"id_2016646"},"menu":{"hasChildren":false},"tocID":"id_2016646-d46e86851","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_20.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e86953","topics":[]},{"title":"Doing the host datapath diagnostic","shortdesc":"<p class=\"shortdesc\">The host datapath diagnostic makes sure of the Ethernet communication links between the host computer and the processor boards within the Integrated Control Engine (ICE).<\/p>","href":"r_diag_Host-Datapath-Diagnostics_12457984.html","attributes":{"data-id":"id_15666846"},"menu":{"hasChildren":true},"tocID":"id_15666846-d46e87055","next":"id_15666846-d46e87055"},{"title":"Doing the host-Image Compute Node (ICN) Ethernet path diagnostic","shortdesc":"<p class=\"shortdesc\">The host-Image Compute Node (ICN) Ethernet path diagnostic makes sure that network connectivity exists between the host and an ICN.<\/p>","href":"c_Host-ICN-Ethernet-Path_15625812.html","attributes":{"data-id":"id_13106466"},"menu":{"hasChildren":true},"tocID":"id_13106466-d46e87259","next":"id_13106466-d46e87259"},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the beginning of some procedures and at the end of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_Parent_18.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e87463","topics":[]}]});